import { Component, Input, Output, EventEmitter, OnInit } from '@angular/core';
import { MisCompras } from 'src/app/models/mis-compras';

@Component({
  selector: 'app-componente-hijo',
  templateUrl: './componente-hijo.component.html',
  styleUrls: ['./componente-hijo.component.css']
})
export class ComponenteHijoComponent{

  @Input() compras: MisCompras[] = [];

}
<div>
  <h3>Detalle de Compras</h3>
  <div *ngFor="let compra of compras">
    <p>Pedido: {{ compra.numPedido }} - Total: {{ compra.total }}€</p>
    <ul>
      <li *ngFor="let producto of compra.productos">
        {{ producto.nombreProd }} - {{ producto.cantidad }} x {{ producto.precio }}€
      </li>
    </ul>
  </div>
</div>
